import axios from 'axios';

const API = axios.create({
  baseURL: 'http://localhost:5000/api'
});

// Auto-add token to every request
API.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// Auth APIs
export const register = (data) => API.post('/auth/register', data);
export const login = (data) => API.post('/auth/login', data);

// Timer APIs
export const getTimers = () => API.get('/timers');
export const createTimer = (name) => API.post('/timers', { name });
export const startTimer = (id) => API.post(`/timers/${id}/start`);
export const pauseTimer = (id) => API.post(`/timers/${id}/pause`);
export const deleteTimer = (id) => API.delete(`/timers/${id}`);
export const getTotalTime = (id) => API.get(`/timers/${id}/total`);

export default API;
